qcmc_logic.djr.validate_dates = function(frm) {
    const now = frappe.datetime.now_datetime();

    if (frm.doc.date_started && frm.doc.date_started > now) {
        frappe.msgprint({ title: __("Invalid Date"), message: __("Date Started cannot be a future date."), indicator: "red" });
        frm.set_value("date_started", "");
        return;
    }
    if (frm.doc.date_finished && frm.doc.date_finished > now) {
        frappe.msgprint({ title: __("Invalid Date"), message: __("Date Finished cannot be a future date."), indicator: "red" });
        frm.set_value("date_finished", "");
        return;
    }
    if (frm.doc.date_started && frm.doc.date_finished && frm.doc.date_started > frm.doc.date_finished) {
        frappe.msgprint({ title: __("Invalid Date"), message: __("Date Started cannot be greater than Date Finished."), indicator: "red" });
        frm.set_value("date_started", "");
    }
};

frappe.ui.form.on("Daily Job Schedule", {
    refresh(frm) {
        qcmc_logic.djs.set_queries(frm);
        qcmc_logic.djs.ensure_process_titles(frm);
    },
    onload(frm) {
        qcmc_logic.djs.set_queries(frm);
    },
    shift(frm) {
        var times = {DS: ["07:00:00", "19:00:00"], NS: ["19:00:00", "07:00:00"]};
        var t = times[frm.doc.shift];
        if (t) { frm.set_value("time_from", t[0]); frm.set_value("time_to", t[1]); }
    },
    before_save(frm) {
        // Auto-fill time_from / time_to based on shift
        var times = {DS: ["07:00:00", "19:00:00"], NS: ["19:00:00", "07:00:00"]};
        var t = times[frm.doc.shift];
        if (t) { frm.doc.time_from = t[0]; frm.doc.time_to = t[1]; }
        if (!frm.doc.sched_date || !frm.doc.shift) return;
        return frappe.db.get_list("Daily Job Schedule", {
            filters: {
                sched_date: frm.doc.sched_date,
                shift: frm.doc.shift,
                name: ["!=", frm.doc.name || ""]
            },
            limit: 1
        }).then(function(results) {
            if (results && results.length > 0) {
                frappe.throw(
                    __("A {0} shift already exists for {1}. Only one {0} shift is allowed per day.",
                        [frm.doc.shift, frm.doc.sched_date])
                );
            }
        });
    }
});

