function apply_rate_field_visibility(frm) {
	const is_administrator = frappe.session.user === "Administrator";
	const has_allow_rate = (frappe.user_roles || []).includes("Allow Rate");
	const can_see_rates = is_administrator || has_allow_rate;

	toggle_rate_fields(frm, can_see_rates);
}

function toggle_rate_fields(frm, show) {
	const hide = !show;

	const fields = [
		"amount",
		"rate",
		"base_rate",
		"base_amount",
		"price_list_rate",
		"base_price_list_rate",
		"discount_and_margin",
		"section_break_1",
		"section_break_25"
		
		
	];

	// 🔹 Try all possible total fields (ERPNext inconsistency)
	const total_fields = [
		"total",
		"net_total",
		"grand_total",
		"rounded_total",
		"total_taxes_and_charges",
		"taxes_section",
		"totals"
	];

	total_fields.forEach(field => {
		if (frm.fields_dict[field]) {
			frm.toggle_display(field, show);
		}
	});

	// 🔹 DOM fallback (for stubborn UI like "Total (PHP)")
	setTimeout(() => {
		total_fields.forEach(field => {
			$(`[data-fieldname="${field}"]`).closest('.form-group').toggle(show);
		});
	}, 100);

	// 🔹 Child table handling
	const grid = frm.fields_dict.items && frm.fields_dict.items.grid;
	if (grid) {
		fields.forEach((fieldname) => {
			grid.set_column_disp(fieldname, show);

			grid.update_docfield_property(fieldname, "hidden", hide ? 1 : 0);
			grid.update_docfield_property(fieldname, "in_list_view", show ? 1 : 0);
		});

		frm.refresh_field("items");
	}
}

