function set_employee_query(frm) {

  frm.set_query("employee", "custom_employees", function (doc) {

    // ✅ EDSA MODE (NO department included)
    if (doc.custom_located_at_edsa) {
      return {
        query: "qcmc_logic.queries.MrfEmp.get_employee",
        filters: {
          company: doc.company,
          designation: doc.designation,
          custom_location: "EDSA"
        }
      };
    }

    // ✅ NORMAL MODE (WITH department)
    return {
      query: "qcmc_logic.queries.MrfEmp.get_employee",
      filters: {
        company: doc.company,
        department: doc.department,
        designation: doc.designation
      }
    };

  });

}

