qcmc_logic.msrp.render_djr_connections = function(frm) {
    if (frm.is_new()) {
        frm.fields_dict.connections_html.$wrapper.html(
            "<p class='text-muted' style='padding:10px'>Save the document first to view connections.</p>"
        );
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Daily Job Report",
            filters: { project_no: frm.doc.name },
            fields: ["name", "djr_id", "process_title", "action_taken", "date_started", "date_finished", "quantity"],
            order_by: "creation asc",
            limit: 100,
        },
        callback(r) {
            const records = r.message || [];
            let html = "";

            if (!records.length) {
                html = "<p class='text-muted' style='padding:10px'>No Daily Job Reports found for this project.</p>";
            } else {
                const rows = records.map(d => `
                    <tr>
                        <td><a href="/app/daily-job-report/${encodeURIComponent(d.name)}" target="_blank">${d.djr_id || d.name}</a></td>
                        <td>${d.process_title || ""}</td>
                        <td>${d.action_taken || ""}</td>
                        <td>${d.date_started ? frappe.datetime.str_to_user(d.date_started) : ""}</td>
                        <td>${d.date_finished ? frappe.datetime.str_to_user(d.date_finished) : ""}</td>
                        <td>${d.quantity || 0}</td>
                    </tr>
                `).join("");

                html = `
                    <div style="padding:10px">
                        <div style="margin-bottom:8px;font-weight:600">${records.length} Daily Job Report${records.length > 1 ? "s" : ""}</div>
                        <table class="table table-bordered table-condensed" style="font-size:13px">
                            <thead style="background:var(--subtle-fg)">
                                <tr>
                                    <th>ID</th>
                                    <th>Process</th>
                                    <th>Action Taken</th>
                                    <th>Date Started</th>
                                    <th>Date Finished</th>
                                    <th>Quantity</th>
                                </tr>
                            </thead>
                            <tbody>${rows}</tbody>
                        </table>
                    </div>
                `;
            }

            frm.fields_dict.connections_html.$wrapper.html(html);
        }
    });
};

