frappe.ui.form.on("Overtime Slip", {

    refresh(frm) {
        // Remove the original Fetch button and replace with our fixed version
        frm.remove_custom_button("Fetch Overtime Details");

        frm.add_custom_button(__("Fetch Overtime Details"), function() {
            if (!frm.doc.employee) {
                frappe.msgprint({ message: __("Please select an Employee first."), indicator: "orange" });
                return;
            }
            if (!frm.doc.start_date || !frm.doc.end_date) {
                frappe.msgprint({ message: __("Please set Start Date and End Date first."), indicator: "orange" });
                return;
            }

            // Check for existing overtime slip for same period
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Overtime Slip",
                    filters: {
                        employee: frm.doc.employee,
                        start_date: ["<=", frm.doc.end_date],
                        end_date: [">=", frm.doc.start_date],
                        docstatus: ["!=", 2],
                        name: ["!=", frm.doc.name || ""]
                    },
                    fields: ["name"],
                    limit: 1
                },
                callback(r) {
                    if (r.message && r.message.length > 0) {
                        frappe.msgprint({
                            title: __("Duplicate Found"),
                            message: __("Overtime Slip <b>{0}</b> already exists for this employee between {1} and {2}.",
                                [r.message[0].name, frm.doc.start_date, frm.doc.end_date]),
                            indicator: "red"
                        });
                        return;
                    }
                    fetch_attendance(frm);
                }
            });
        }).addClass("btn-primary");
    }
});

function fetch_attendance(frm) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Attendance",
            filters: {
                employee: frm.doc.employee,
                attendance_date: ["between", [frm.doc.start_date, frm.doc.end_date]],
                docstatus: 1,
                overtime_type: ["!=", ""],
                actual_overtime_duration: [">", 0]
            },
            fields: ["name", "attendance_date", "overtime_type", "actual_overtime_duration", "standard_working_hours"],
            limit: 500,
            order_by: "attendance_date asc"
        },
        callback(r) {
            if (!r.message || r.message.length === 0) {
                frappe.msgprint({
                    title: __("No OT Records Found"),
                    message: __("No attendance records with overtime found for <b>{0}</b> between {1} and {2}.<br><br>Make sure attendance is marked with Overtime Type and Overtime Duration.",
                        [frm.doc.employee, frm.doc.start_date, frm.doc.end_date]),
                    indicator: "orange"
                });
                return;
            }

            // Clear existing rows
            frm.clear_table("overtime_details");

            let total_ot = 0;

            // Populate from attendance
            r.message.forEach(att => {
                let row = frm.add_child("overtime_details");
                row.reference_document = att.name;
                row.date = att.attendance_date;
                row.overtime_type = att.overtime_type;
                row.overtime_duration = att.actual_overtime_duration;
                row.standard_working_hours = att.standard_working_hours || 8;
                total_ot += att.actual_overtime_duration;
            });

            frm.set_value("total_overtime_duration", total_ot);
            frm.refresh_field("overtime_details");
            frm.refresh_field("total_overtime_duration");

            frappe.msgprint({
                title: __("Done!"),
                message: __("{0} OT record(s) fetched. Total: <b>{1} hrs</b>. Review and click Save.", 
                    [r.message.length, total_ot]),
                indicator: "green"
            });
        }
    });
}

