function apply_action_filter(frm) {
    const allowed_actions = frm.doc.is_return
        ? ['Return']
        : ['Transfer', 'Receive'];

    const all_actions = ['Transfer', 'Receive', 'Return'];

    // Workflow actions inside the Actions dropdown
    frm.page.wrapper
        .find('.actions-btn-group .dropdown-menu .dropdown-item, .actions-btn-group .dropdown-menu a')
        .each(function () {
            const button = $(this);
            const action_name = button.text().trim();

            if (all_actions.includes(action_name)) {
                button.toggle(allowed_actions.includes(action_name));
            }
        });

    // Handles workflow actions displayed as individual buttons
    frm.page.wrapper
        .find('button')
        .each(function () {
            const button = $(this);
            const action_name = button.text().trim();

            if (all_actions.includes(action_name)) {
                button.toggle(allowed_actions.includes(action_name));
            }
        });
}

