qcmc_logic.sales_order_customer_items.restore_selected_rate_later = function(frm, cdt, cdn) {
    const child = locals[cdt] && locals[cdt][cdn];
    if (
        !child ||
        !qcmc_logic.sales_order_customer_items.has_customer_history_rate(child) ||
        child.__applying_customer_history_rate
    ) {
        return;
    }

    qcmc_logic.sales_order_customer_items.restore_selected_rate_after_delay(frm, cdt, cdn, 0);
};

qcmc_logic.sales_order_customer_items.restore_selected_rate_after_delay = function(frm, cdt, cdn, delay) {
    setTimeout(function() {
        const current_child = locals[cdt] && locals[cdt][cdn];
        if (
            !current_child ||
            !qcmc_logic.sales_order_customer_items.has_customer_history_rate(current_child) ||
            current_child.__applying_customer_history_rate
        ) {
            return;
        }

        const selected_rate = qcmc_logic.sales_order_customer_items.get_customer_history_rate(current_child);
        if (
            qcmc_logic.sales_order_customer_items.parse_rate(current_child.rate) === selected_rate &&
            qcmc_logic.sales_order_customer_items.parse_rate(current_child.price_list_rate) === selected_rate
        ) {
            return;
        }

        qcmc_logic.sales_order_customer_items.apply_selected_rate(
            frm,
            current_child,
            selected_rate
        );
    }, delay);
};

qcmc_logic.sales_order_customer_items.has_customer_history_rate = function(child) {
    return Boolean(child.custom_customer_history_rate_selected) &&
        child.custom_customer_history_rate !== undefined &&
        child.custom_customer_history_rate !== null &&
        child.custom_customer_history_rate !== "";
};

qcmc_logic.sales_order_customer_items.get_customer_history_rate = function(child) {
    return qcmc_logic.sales_order_customer_items.parse_rate(child.custom_customer_history_rate);
};

qcmc_logic.sales_order_customer_items.rate_precision = function() {
    return cint(frappe.boot.sysdefaults.currency_precision || frappe.boot.sysdefaults.float_precision || 4);
};

qcmc_logic.sales_order_customer_items.parse_rate = function(value) {
    return flt(value, qcmc_logic.sales_order_customer_items.rate_precision());
};

