            row.custom_customer_history_rate = 0;
            row.custom_customer_history_item_code = "";
            frappe.model.set_value(cdt, cdn, {
                custom_customer_history_rate_selected: 0,
                custom_customer_history_rate: 0,
                custom_customer_history_item_code: ""
            });
        }
        if (!frm.doc.customer || !row.item_code || !frm.doc.company) return;

        frappe.call({
            method: "qcmc_logic.customs.sales_order.get_previous_item_rates",
            args: {
                customer: frm.doc.customer,
                item_code: row.item_code,
                company: frm.doc.company
            },
            callback: function (r) {
                const rates = r.message || r.data || [];
                const selected_rate = row.custom_customer_history_rate_selected ? row.custom_customer_history_rate : null;
                if (selected_rate || rates.length > 0) {
                    frappe.model.set_value(cdt, cdn, 'rate', selected_rate || rates[0].rate);
                }
            }
        });
    },

    custom_select_previous_rate: function (frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!frm.doc.customer || !row.item_code || !frm.doc.company) {
            frappe.msgprint("Please select a customer, company and item first.");
            return;
        }

        frappe.call({
            method: "qcmc_logic.customs.sales_order.get_previous_item_rates",
            args: {
                customer: frm.doc.customer,
                item_code: row.item_code,
                company: frm.doc.company
            },
            callback: function (r) {
                const rates = r.message || r.data || [];
                if (rates.length > 0) {
                    let html = `
                        <table class="table table-bordered" style="margin-top:10px;">
                            <thead>
                                <tr>
                                    <th>Select</th>
                                    <th>Rate</th>
                                    <th>UOM</th>
                                    <th>First Used</th>
                                    <th>Last Used</th>
                                    <th>Times Used</th>
                                </tr>
                            </thead>
                            <tbody>
                    `;

                    rates.forEach((entry, index) => {
                        const currency = entry.currency || frm.doc.currency || "";
                        const formatted_rate = format_currency(entry.rate, currency);
                        const first_used = entry.first_transaction_date ? frappe.datetime.str_to_user(entry.first_transaction_date) : "";
                        const last_used = entry.last_transaction_date ? frappe.datetime.str_to_user(entry.last_transaction_date) : "";

                        html += `
                            <tr>
                                <td><input type="radio" name="rate_option" value="${entry.rate}" ${index === 0 ? "checked" : ""}></td>
                                <td>${formatted_rate}</td>
                                <td>${entry.uom || ""}</td>
                                <td>${first_used}</td>
                                <td>${last_used}</td>
                                <td>${entry.times_used || 0}</td>
                            </tr>
                        `;
                    });

                    html += `</tbody></table>`;

                    let d = new frappe.ui.Dialog({
                        title: 'Select Rate from Customer History',
                        fields: [
                            {
                                fieldtype: 'HTML',
                                fieldname: 'rates_table',
                                options: html
                            }
                        ],
                        primary_action_label: 'Set Rate',
                        primary_action() {
                            let selected = d.$wrapper.find('input[name="rate_option"]:checked').val();
                            if (selected) {
                                frappe.model.set_value(cdt, cdn, {
                                    custom_customer_history_rate_selected: 1,
                                    custom_customer_history_rate: selected,
                                    custom_customer_history_item_code: row.item_code,
                                    price_list_rate: selected,
                                    rate: selected,
                                    discount_percentage: 0,
                                    discount_amount: 0
                                });
                            }
                            d.hide();
                        }
                    });

                    d.show();
                } else {
                    frappe.msgprint("No previous rates found for this item and customer.");
                }
            }
        });
    }
});

