function render_qr_modal(docname) {
    const uid = 'qr-' + Date.now();
    const d = new frappe.ui.Dialog({
        title: __('QR Code \u2014 {0}', [docname]),
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'qr_html',
