                    <div id="${uid}"></div>
                    <p style="font-size:13px;color:var(--text-muted);margin:0;">${docname}</p>
                </div>`
            }
        ],
        primary_action_label: __('Close'),
        primary_action() { d.hide(); }
    });
    d.show();
    setTimeout(() => {
        const el = document.getElementById(uid);
        if (el) {
            new QRCode(el, {
                text: docname,
                width: 200,
                height: 200,
                colorDark: '#000000',
                colorLight: '#ffffff',
                correctLevel: QRCode.CorrectLevel.H
            });
        }
    }, 200);
}

