// Work Order: Custom Print Format based on Workstation
// Priority:
// 1. Operation with "Is Final Finished Good" checked
// 2. Last operation with workstation
// 3. BOM Operation fallback

frappe.ui.form.on('Work Order', {
    refresh: function(frm) {
        frm.print_doc = function() {
            handle_custom_print(frm);
        };

        if (frm.toolbar && frm.toolbar.print_me) {
            frm.toolbar.print_me = function() {
                handle_custom_print(frm);
            };
        }

        frm.add_custom_button(__('Print'), function() {
            handle_custom_print(frm);
        }).removeClass('btn-default').addClass('btn-primary');
    }
});

async function handle_custom_print(frm) {
    try {
        let workstation = null;

        // 1. Get workstation from Work Order Operations
        if (frm.doc.operations && frm.doc.operations.length > 0) {
            console.table(frm.doc.operations.map(op => ({
                idx: op.idx,
                operation: op.operation,
                workstation: op.workstation,
                is_final_finished_good: op.is_final_finished_good
            })));

            // Prefer row checked as Final Finished Good
            let final_op = frm.doc.operations.find(op =>
                op.workstation && cint(op.is_final_finished_good) === 1
            );

            // Fallback to last operation with workstation
            let last_op = [...frm.doc.operations]
                .reverse()
                .find(op => op.workstation);

            workstation = final_op?.workstation || last_op?.workstation || null;
        }

        // 2. Fallback: get workstation from BOM Operation
        if (!workstation && frm.doc.bom_no) {
            const bom_res = await frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'BOM Operation',
                    filters: [
                        ['parent', '=', frm.doc.bom_no],
                        ['parenttype', '=', 'BOM']
                    ],
                    fields: [
                        'workstation',
                        'idx',
                        'is_final_finished_good'
                    ],
                    order_by: 'idx desc',
                    limit_page_length: 20
                }
            });

            if (bom_res.message && bom_res.message.length > 0) {
                let final_bom_op = bom_res.message.find(op =>
                    op.workstation && cint(op.is_final_finished_good) === 1
                );

                let last_bom_op = bom_res.message.find(op => op.workstation);

                workstation = final_bom_op?.workstation || last_bom_op?.workstation || null;
            }
        }

        let print_format = null;

        // 3. Get custom print format from Workstation
        if (workstation) {
            const ws_res = await frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Workstation',
                    filters: {
                        name: workstation
                    },
                    fieldname: 'custom_print_format'
                }
            });

            if (ws_res.message && ws_res.message.custom_print_format) {
                print_format = ws_res.message.custom_print_format;
            }
        }

        console.log('[WO Print]', {
            workstation: workstation,
            print_format: print_format
        });

        if (!print_format) {
            frappe.msgprint(__('No custom print format found for workstation: ') + (workstation || 'None'));
        }

        let url = '/printview?' + $.param({
            doctype: frm.doc.doctype,
            name: frm.doc.name,
            format: print_format || '',
            no_letterhead: 0
        });

        let w = window.open(url);

        if (!w) {
            frappe.msgprint(__('Please allow pop-ups to continue.'));
        }

    } catch (err) {
        console.error('[WO Print] Error:', err);

        window.open('/printview?' + $.param({
            doctype: frm.doc.doctype,
            name: frm.doc.name
        }));
    }
}

