function preview_logs(frm, values) {
	frappe.call({
		method: "zkteco_integration.zkteco_integration.zk_downloader.preview_attendance_for_device",
		args: {
			device_name: frm.doc.name,
			start_date: values.from_date,
			end_date: values.to_date,
		},
		freeze: true,
		freeze_message: __("Reading device logs..."),
		callback: (r) => {
			const preview = r.message;
			if (!preview || !preview.success) return;

			const c = preview.counts;
			const escape = frappe.utils.escape_html;
			const rows = preview.rows.map((row) => `
				<tr>
					<td>${escape(row.time)}</td>
					<td>${escape(row.biometric_id)}</td>
					<td>${escape(row.employee_name || "—")}</td>
					<td>${escape(row.status)}</td>
				</tr>`).join("");
			const limited = preview.rows_limited
				? `<p class="text-muted">${__("Showing the first 250 logs.")}</p>`
				: "";
			const warning = preview.location_warning
				? `<div class="alert alert-warning">${escape(preview.location_warning)}</div>`
				: "";

			const dialog = new frappe.ui.Dialog({
				title: __("Confirm Employee Checkins"),
				size: "extra-large",
				fields: [{
					fieldname: "preview",
					fieldtype: "HTML",
					options: `
						${warning}
						<p>
							${__("Total")}: <b>${c.total}</b> &nbsp;
							${__("Ready")}: <b class="text-success">${c.ready}</b> &nbsp;
							${__("Duplicates")}: <b>${c.duplicates}</b> &nbsp;
							${__("Missing Employees")}: <b class="text-danger">${c.missing}</b>
						</p>
						${limited}
						<div style="max-height: 420px; overflow: auto">
							<table class="table table-bordered table-sm">
								<thead><tr>
									<th>${__("Time")}</th>
									<th>${__("Biometric ID")}</th>
									<th>${__("Employee")}</th>
									<th>${__("Status")}</th>
								</tr></thead>
								<tbody>${rows}</tbody>
							</table>
						</div>`,
				}],
				primary_action_label: __("Confirm and Create Checkins"),
				primary_action() {
					dialog.hide();
					create_checkins(frm, values);
				},
			});
			if (!c.ready || preview.location_warning) {
				dialog.get_primary_btn().prop("disabled", true);
			}
			dialog.show();
		},
	});
}

function create_checkins(frm, values) {
	frappe.call({
		method: "zkteco_integration.zkteco_integration.zk_downloader.fetch_attendance_for_device",
		args: {
			device_name: frm.doc.name,
			start_date: values.from_date,
			end_date: values.to_date,
		},
		freeze: true,
		freeze_message: __("Creating Employee Checkins..."),
		callback: (r) => {
			const s = r.message || {};
			frappe.msgprint({
				title: s.success ? __("Import Complete") : __("Import Failed"),
				indicator: s.success ? "green" : "red",
				message: `${__("Inserted")}: <b>${s.inserted_logs || 0}</b><br>
					${__("Duplicates skipped")}: <b>${s.skipped_duplicates || 0}</b><br>
					${__("Missing employees")}: <b>${s.missing_employees || 0}</b>
					${s.errors && s.errors.length ? `<br>${s.errors.map(frappe.utils.escape_html).join("<br>")}` : ""}`,
			});
			frm.reload_doc();
		},
	});
}

frappe.ui.form.on('ZKTeco Log Downloader', {
    refresh(frm) {
        frm.add_custom_button(__('Download from All Devices'), function() {
        frappe.call({
        method: "zkteco_integration.zkteco_integration.doctype.zkteco_log_downloader.zkteco_log_downloader.download_all_logs",
        freeze: true,
        freeze_message: __("Downloading logs..."),
        callback: function(r) {
        frappe.msgprint(r.message || "Logs downloaded successfully!");
        }
        });
        });
    }
});
